presetParts.comp:
#define sat saturate
sampler sampler_pw_noise_lq;
float stars, smask, gmask;
float2 dz, uv0, uv1,uv2, uv3, uv4,smoke;
float3 rs, rs2, rs0, gnd, gnd1, gnd2,screen,rip;
static const float3 t = float3(q20,q23,q26), s = float3(q22,q25,q28);
static const float3 ts = cross(t,s);
static const float2 hor = texsize.zw*float2(2,0), ver = texsize.zw*float2(0,2);
static const float3 centre = float3(q7,q8,q9);
static const float abo=sat(40*q27), gk = max(1,10/q9), tstars = time*0.01;

float3 col (float c) {return pow (c,1+1.5*roam_sin);}

float2 noise3 (float2 uvi) {uvi*=0.75;
  return sat(tex2D(sampler_noise_hq,uvi)
         +tex2D(sampler_noise_hq,uvi*4)/3-0.4); }

float3 tile (float2 uvi)
  {return tex2D(sampler_pw_noise_lq,uvi);} 

float3 project () {float z; 
  z = .08/mul(ts,screen); //z = min(1.,max(-1,z));
  return float3((mul(float2x3(t,s),cross(ts,cross(centre,screen)))*z),-z);}

shader_body {
uv += 0*texsize.zw/2; uv0 = uv;
dz.x = 2.0*GetBlur1(uv+hor*gk).g-2.0*GetBlur1(uv-hor*gk).g;
dz.y = 2.0*GetBlur1(uv+ver*gk).g-2.0*GetBlur1(uv-ver*gk).g;
dz *= GetBlur1(uv).g > 0.06;
dz *= max(1,GetBlur2(uv).g*8);

screen = float3 ((uv-0.5)*aspect.xy+dz*0.25,1);
rs = project(); float lrs = length(rs.xy);
gmask = sat (1-.1*lrs) * (rs.z>0);
gmask *= sat (2-10*min(abs(rs.x),abs(rs.y)));
float gm0 = gmask;
uv2 = (rs)*0.15/(1+lrs*0.25);
uv2 += float2(0,q30)* (abs (uv2.x) < 3.0/4/64);

rip = tex2D(sampler_noise_lq,uv2*32*tex2D(sampler_pw_noise_lq,uv2));
gnd1 = tile(uv2); 
gnd2 = tile(uv2+0.0002*float2(q17,q18)); 
gmask = sat (gmask*3-2*dot(gnd1,gnd1));
gnd  = sat(gnd1 + lum(gnd1-gnd2)*3);
float zblend = sat(abo-lrs/8);
smoke = 0.06*noise3(uv2-tstars*4).xy *zblend;

stars = 0; smask = 0;
uv4 = uv2*.1 +tstars*float2(1,0.02) + 0.01*gnd;
smask = tex2D (sampler_pw_noise_lq,uv4)>.8;
stars = 1/length(abs(frac(uv4*256+ rip*0.1)-.5))*smask;

uv4 = uv2*.1 +tstars*float2(0.02,1) + 0.01*gnd;
//uv4 = uv4.yx;
smask = tex2D (sampler_pw_noise_lq,uv4)>.8;
//stars += 1/length(abs(frac(uv4*256+ rip*0.1)-.5))*smask;

ret.b += (1-uv.y)*0.2;
ret += gnd*gmask*(.15+stars*stars*0.01)*abo;

// Dioden
uv4 = uv0+dz*0.05;
float3 dio = max(1.5*max(GetPixel(uv4).r,GetBlur1(uv4).r),GetBlur3(uv4).r);
ret += col(dio)*q3;

// Spiegelung
float2 dref = rip.xy*0.02;
float2 uvm = uv4-dref;
float3 mirr = GetBlur1(uvm).b;
ret += gmask*abo * (uv0.y < 0.99)* (uv0.y > 0.01)* col(mirr)*(1+gnd) ;

//smoke
ret += smoke.x*q19;

//orb
uv1 = ((uv0-0.5)-float2(q15,-q16))*aspect.xy+dz*0.2;
ret += 0.00015/pow(length(uv1),2)*treb;
uv1 = ((uv0-0.5)-float2(q5,-q6))*aspect.xy+rip*.02;
ret += 0.0007/pow(length(uv1+dref),2)*abo*treb*gnd*gmask;


//Glas
float refl = GetBlur1(uv0+dz*0.25).g/2;
ret += refl*(1+roam_cos);

//back light
float bl = 0;
uv1 = ((uv0-0.5)-rs*0-float2(q1,-q2))*aspect.xy+dz*4;
bl += .07/length(uv1)*sat(1-gm0);;
uv1 = ((uv0-0.5)-rs*0-float2(q10,-q12))*aspect.xy+gnd*0.1+dz*2+rip*.0;
bl += pow(.07/length(uv1),2)*gmask;

ret += q31*bl*(1+mid_att/2)*sat(1-smoke.x*32*rand_preset.x)*roam_cos;

ret = 1-exp(-ret*1.8);
}

